#include "cwhip/Diagnostic.hpp"

#include <utility>

namespace cwhip {

std::string formatDiagnostic(const SourceLocation& location, const std::string& message) {
    return location.file + ":" + std::to_string(location.line) + ":" +
           std::to_string(location.column) + ": error: " + message;
}

DiagnosticError::DiagnosticError(SourceLocation location, const std::string& message)
    : std::runtime_error(formatDiagnostic(location, message)), location_(std::move(location)) {}

const SourceLocation& DiagnosticError::location() const noexcept {
    return location_;
}

} // namespace cwhip
